function processPayment(payment) {
  switch (payment.type) {
    case 'card':
      validateCard(payment.details);
      chargeCard(payment.details);
      break;
    case 'bank':
      validateBank(payment.details);
      transferFunds(payment.details);
      break;
  }
}

