class PricingService {
  calculate(order) {
    let total = 0;
    if (order.customer.isVip) total += this.vipDiscount(order);
    if (order.items.length > 10) total += this.bulkDiscount(order);
    if (order.region === 'EU') total += this.euTax(order);
    return total;
  }
}

